// src/App.js
import React, { useState, useEffect, useRef } from 'react';
import * as THREE from 'three';
import LoginModal from './components/LoginModal';

function App() {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [user, setUser] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [analytics, setAnalytics] = useState({
    totalUsers: 1247,
    activeProjects: 342,
    completedTasks: 8921,
    revenue: 456789
  });
  const [recentActivities, setRecentActivities] = useState([
    { id: 1, user: 'Ahmed Ali', action: 'Completed project', time: '2 min ago', avatar: '👨‍💻' },
    { id: 2, user: 'Sarah Khan', action: 'Started new task', time: '15 min ago', avatar: '👩‍💻' },
    { id: 3, user: 'Omar Hassan', action: 'Submitted report', time: '1 hour ago', avatar: '👨‍🔧' },
    { id: 4, user: 'Fatima Noor', action: 'Joined Decode Labs', time: '3 hours ago', avatar: '👩‍🎓' },
    { id: 5, user: 'Zain Malik', action: 'Earned certificate', time: '5 hours ago', avatar: '🏆' }
  ]);

  const mountRef = useRef(null);
  const sceneRef = useRef(null);
  const cameraRef = useRef(null);
  const rendererRef = useRef(null);

  // Check for existing session
  useEffect(() => {
    const checkAuth = () => {
      try {
        const storedUser = localStorage.getItem('user');
        const isLoggedIn = localStorage.getItem('isLoggedIn');

        if (storedUser && isLoggedIn === 'true') {
          const userData = JSON.parse(storedUser);
          setUser(userData);
        }
      } catch (error) {
        console.error('Auth check error:', error);
      } finally {
        setIsLoading(false);
      }
    };

    checkAuth();
  }, []);

  // Initialize Decode Labs themed Three.js Scene
  useEffect(() => {
    if (!mountRef.current) return;

    // Scene setup
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x0a0a2a);
    scene.fog = new THREE.FogExp2(0x0a0a2a, 0.008);
    sceneRef.current = scene;

    // Camera setup
    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(0, 2, 8);
    camera.lookAt(0, 0, 0);
    cameraRef.current = camera;

    // Renderer setup
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(window.devicePixelRatio);
    mountRef.current.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    // Lighting
    const ambientLight = new THREE.AmbientLight(0x222222);
    scene.add(ambientLight);

    const mainLight = new THREE.DirectionalLight(0xffffff, 1);
    mainLight.position.set(5, 10, 7);
    scene.add(mainLight);

    const backLight = new THREE.PointLight(0x4466ff, 0.5);
    backLight.position.set(0, 2, -5);
    scene.add(backLight);

    const fillLight = new THREE.PointLight(0xff66cc, 0.3);
    fillLight.position.set(3, 1, 2);
    scene.add(fillLight);

    // Decode Labs Logo Effect - Rotating Cube with Code
    const cubeGroup = new THREE.Group();

    // Main cube
    const geometry = new THREE.BoxGeometry(1.5, 1.5, 1.5);
    const materials = [
      new THREE.MeshStandardMaterial({ color: 0x667eea, metalness: 0.7, roughness: 0.3 }),
      new THREE.MeshStandardMaterial({ color: 0x764ba2, metalness: 0.7, roughness: 0.3 }),
      new THREE.MeshStandardMaterial({ color: 0x48bb78, metalness: 0.7, roughness: 0.3 }),
      new THREE.MeshStandardMaterial({ color: 0xed8936, metalness: 0.7, roughness: 0.3 }),
      new THREE.MeshStandardMaterial({ color: 0x667eea, metalness: 0.7, roughness: 0.3 }),
      new THREE.MeshStandardMaterial({ color: 0x764ba2, metalness: 0.7, roughness: 0.3 })
    ];
    const cube = new THREE.Mesh(geometry, materials);
    cube.castShadow = true;
    cube.receiveShadow = true;
    cubeGroup.add(cube);

    // Wireframe cube around it
    const wireframeGeo = new THREE.BoxGeometry(1.7, 1.7, 1.7);
    const wireframeMat = new THREE.MeshBasicMaterial({ color: 0x667eea, wireframe: true, transparent: true, opacity: 0.3 });
    const wireframeCube = new THREE.Mesh(wireframeGeo, wireframeMat);
    cubeGroup.add(wireframeCube);

    scene.add(cubeGroup);

    // Floating particles (code symbols)
    const particleCount = 800;
    const particleGeometry = new THREE.BufferGeometry();
    const particlePositions = new Float32Array(particleCount * 3);
    const particleColors = new Float32Array(particleCount * 3);

    for (let i = 0; i < particleCount; i++) {
      particlePositions[i * 3] = (Math.random() - 0.5) * 15;
      particlePositions[i * 3 + 1] = (Math.random() - 0.5) * 8;
      particlePositions[i * 3 + 2] = (Math.random() - 0.5) * 15 - 5;

      const color = new THREE.Color().setHSL(0.6 + Math.random() * 0.2, 1, 0.5);
      particleColors[i * 3] = color.r;
      particleColors[i * 3 + 1] = color.g;
      particleColors[i * 3 + 2] = color.b;
    }

    particleGeometry.setAttribute('position', new THREE.BufferAttribute(particlePositions, 3));
    particleGeometry.setAttribute('color', new THREE.BufferAttribute(particleColors, 3));

    const particleMaterial = new THREE.PointsMaterial({ size: 0.05, vertexColors: true, transparent: true, opacity: 0.6 });
    const particles = new THREE.Points(particleGeometry, particleMaterial);
    scene.add(particles);

    // Floating code rings
    const ringGeometry = new THREE.TorusGeometry(2.5, 0.05, 64, 200);
    const ringMaterial = new THREE.MeshStandardMaterial({ color: 0x667eea, emissive: 0x3344aa, emissiveIntensity: 0.5 });
    const ring = new THREE.Mesh(ringGeometry, ringMaterial);
    ring.rotation.x = Math.PI / 2;
    scene.add(ring);

    const ring2Geometry = new THREE.TorusGeometry(3.2, 0.03, 64, 200);
    const ring2Material = new THREE.MeshStandardMaterial({ color: 0x48bb78, emissive: 0x226622, emissiveIntensity: 0.3 });
    const ring2 = new THREE.Mesh(ring2Geometry, ring2Material);
    ring2.rotation.z = Math.PI / 3;
    scene.add(ring2);

    // Ground grid
    const gridHelper = new THREE.GridHelper(20, 20, 0x667eea, 0x334466);
    gridHelper.position.y = -2;
    gridHelper.material.transparent = true;
    gridHelper.material.opacity = 0.3;
    scene.add(gridHelper);

    // Animation
    let time = 0;
    const animate = () => {
      requestAnimationFrame(animate);
      time += 0.01;

      cubeGroup.rotation.y = time * 0.5;
      cubeGroup.rotation.x = Math.sin(time * 0.3) * 0.2;
      cubeGroup.rotation.z = Math.cos(time * 0.2) * 0.1;

      ring.rotation.z += 0.005;
      ring.rotation.y += 0.003;
      ring2.rotation.x += 0.004;
      ring2.rotation.y -= 0.002;

      particles.rotation.y += 0.001;
      particles.rotation.x += 0.0005;

      camera.position.x += (Math.sin(time * 0.2) * 0.3 - camera.position.x) * 0.02;
      camera.position.y += (Math.cos(time * 0.3) * 0.2 + 2 - camera.position.y) * 0.02;
      camera.lookAt(0, 0, 0);

      renderer.render(scene, camera);
    };

    animate();

    const handleResize = () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      if (mountRef.current && renderer.domElement) {
        mountRef.current.removeChild(renderer.domElement);
      }
      renderer.dispose();
    };
  }, []);

  const handleLoginSuccess = (userData) => {
    setUser(userData);
    setIsModalOpen(false);
  };

  const handleLogout = () => {
    localStorage.removeItem('user');
    localStorage.removeItem('isLoggedIn');
    setUser(null);
  };

  if (isLoading) {
    return (
      <div style={styles.loadingContainer}>
        <div style={styles.loadingSpinner} />
        <style>{`
          @keyframes spin {
            to { transform: rotate(360deg); }
          }
        `}</style>
        <p>Loading Decode Labs Dashboard...</p>
      </div>
    );
  }

  return (
    <div style={styles.app}>
      {/* Three.js Background */}
      <div ref={mountRef} style={styles.canvasContainer} />

      {/* Navigation */}
      <nav style={styles.navbar}>
        <div style={styles.navContainer}>
          <div style={styles.logo}>
            <h1 style={styles.logoText}>Decode Labs</h1>
            <span style={styles.logoBadge}>DASHBOARD</span>
          </div>

          <div style={styles.navMenu}>
            {['dashboard', 'projects', 'analytics', 'team'].map(tab => (
              <button
                key={tab}
