              </div>

              {/* Quick Actions */}
              <div style={styles.quickActionsCard}>
                <h3 style={styles.cardTitle}>Quick Actions</h3>
                <div style={styles.actionsGrid}>
                  {[
                    { icon: '📝', label: 'New Project', color: '#667eea' },
                    { icon: '✓', label: 'Add Task', color: '#48bb78' },
                    { icon: '👥', label: 'Invite Team', color: '#ed8936' },
