                    <button key={i} style={{ ...styles.actionButton, background: action.color }}>
                      <span style={styles.actionIcon}>{action.icon}</span>
                      {action.label}
                    </button>
                  ))}
                </div>

                <div style={styles.progressSection}>
                  <h4 style={styles.progressTitle}>Project Completion</h4>
                  <div style={styles.progressBar}>
                    <div style={{ ...styles.progressFill, width: '68%' }}></div>
                  </div>
                  <p style={styles.progressText}>68% overall completion rate</p>
                </div>
              </div>
            </div>

            {/* Projects Table */}
            <div style={styles.projectsCard}>
              <h3 style={styles.cardTitle}>Active Projects</h3>
              <div style={styles.tableContainer}>
                <table style={styles.table}>
                  <thead>
                    <tr style={styles.tableHeader}>
                      <th style={styles.tableTh}>Project Name</th>
                      <th style={styles.tableTh}>Status</th>
                      <th style={styles.tableTh}>Progress</th>
                      <th style={styles.tableTh}>Team</th>
                      <th style={styles.tableTh}>Due Date</th>
                    </tr>
                  </thead>
                  <tbody>
                    {[
                      { name: 'Decode Dashboard', status: 'Active', progress: 85, team: 4, due: 'Dec 15, 2026' },
                      { name: 'AI Learning Platform', status: 'In Progress', progress: 62, team: 6, due: 'Jan 10, 2026' },
                      { name: 'Mobile App Dev', status: 'Review', progress: 94, team: 3, due: 'Dec 5, 2026' },
                      { name: 'Cloud Migration', status: 'Planning', progress: 25, team: 5, due: 'Feb 1, 2026' }
                    ].map((project, i) => (
                      <tr key={i} style={styles.tableRow}>
                        <td style={styles.tableTd}>{project.name}</td>
                        <td style={styles.tableTd}>
                          <span style={{ ...styles.statusBadge, background: 
                            project.status === 'Active' ? '#48bb7820' : 
                            project.status === 'In Progress' ? '#ed893620' : 
                            project.status === 'Review' ? '#667eea20' : '#e74c3c20',
                            color: 
                            project.status === 'Active' ? '#48bb78' : 
                            project.status === 'In Progress' ? '#ed8936' : 
                            project.status === 'Review' ? '#667eea' : '#e74c3c'
                          }}>
                            {project.status}
                          </span>
                        </td>
                        <td style={styles.tableTd}>
                          <div style={styles.tableProgress}>
                            <div style={{ ...styles.tableProgressFill, width: `${project.progress}%` }}></div>
                            <span style={styles.progressPercent}>{project.progress}%</span>
                          </div>
                        </td>
                        <td style={styles.tableTd}>{project.team} members</td>
                        <td style={styles.tableTd}>{project.due}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer style={styles.footer}>
        <div style={styles.footerContent}>
          <p>© 2026 Decode Labs. All rights reserved.</p>
          <div style={styles.footerLinks}>
            <a href="#" style={styles.footerLink}>About</a>
            <a href="#" style={styles.footerLink}>Privacy</a>
            <a href="#" style={styles.footerLink}>Terms</a>
            <a href="#" style={styles.footerLink}>Contact</a>
          </div>
        </div>
      </footer>

      <LoginModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onLoginSuccess={handleLoginSuccess} />

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes slideIn {
          from { opacity: 0; transform: translateX(-20px); }
          to { opacity: 1; transform: translateX(0); }
        }
        button:hover { transform: translateY(-2px) !important; }
      `}</style>
    </div>
  );
}

